export const KEY='pocket-kitten-companion-v1';
export const clamp=v=>Math.max(0,Math.min(100,Number.isFinite(v)?v:0));
export function fresh(now=Date.now()){return {name:'Mochi',food:82,water:85,happiness:88,energy:78,cleanliness:92,bond:0,cuddles:0,sleeping:false,born:now,updated:now,sound:false,catVolume:.8,roomVolume:.4,journal:[{text:'A little friendship begins.',icon:'♡',time:now}]};}
export function restore(raw,now=Date.now()){const d=fresh(now);if(!raw||typeof raw!=='object')return d;for(const key of ['food','water','happiness','energy','cleanliness'])if(Number.isFinite(raw[key]))d[key]=clamp(raw[key]);for(const key of ['bond','cuddles'])if(Number.isFinite(raw[key]))d[key]=Math.max(0,raw[key]);if(typeof raw.name==='string'&&raw.name.trim())d.name=raw.name.trim().slice(0,24);d.sleeping=raw.sleeping===true;d.sound=raw.sound===true;for(const key of ['catVolume','roomVolume'])if(Number.isFinite(raw[key]))d[key]=Math.min(1,Math.max(0,raw[key]));if(Number.isFinite(raw.born)&&raw.born<=now)d.born=raw.born;if(Number.isFinite(raw.updated))d.updated=Math.min(now,raw.updated);if(Array.isArray(raw.journal))d.journal=raw.journal.filter(x=>x&&typeof x.text==='string'&&Number.isFinite(x.time)).slice(0,12);return advance(d,now);}
export function advance(p,now=Date.now()){const hours=Math.max(0,Math.min(12,(now-p.updated)/3600000));p.food=clamp(p.food-hours*3);p.water=clamp((Number.isFinite(p.water)?p.water:85)-hours*(p.sleeping?1.5:3.5));p.happiness=clamp(p.happiness-hours*(p.sleeping?1:2));p.cleanliness=clamp(p.cleanliness-hours*1.4);p.energy=clamp(p.energy+hours*(p.sleeping?25:-2.5));p.updated=now;return p;}
export function care(p,action,snack='kibble'){if(p.sleeping&&action!=='sleep')return {ok:false,message:'A little sleepy. Wake your kitten first.'};if(action==='feed'){if(p.food>94)return {ok:false,message:'That tummy is full. Save a snack for later.'};p.food=clamp(p.food+({kibble:24,salmon:30,chicken:27}[snack]??24));p.happiness=clamp(p.happiness+5);p.cleanliness=clamp(p.cleanliness-2);p.bond+=3;}else if(action==='drink'){if(p.water>94)return {ok:false,message:'Not thirsty right now.'};p.water=clamp(p.water+35);p.happiness=clamp(p.happiness+2);p.bond+=1;}else if(action==='play'){if(p.energy<15)return {ok:false,message:'A little rest first. Playtime can wait.'};p.happiness=clamp(p.happiness+18);p.energy=clamp(p.energy-10);p.food=clamp(p.food-3);p.bond+=6;}else if(action==='brush'){p.cleanliness=clamp(p.cleanliness+30);p.happiness=clamp(p.happiness+5);p.bond+=3;}else if(action==='pet'){p.happiness=clamp(p.happiness+3);p.cuddles++;p.bond++;}else if(action==='sleep'){p.sleeping=!p.sleeping;}else return {ok:false,message:'Unknown action'};return {ok:true};}
export function mood(p){if(p.sleeping)return 'Dreaming softly';if(p.food<25)return 'A little hungry';if(p.water<25)return 'A little thirsty';if(p.energy<25)return 'Ready for a nap';if(p.cleanliness<30)return 'Needs a little brush';if(p.happiness<35)return 'Missing you';return 'Feeling lovely';}
